function out = density_matrix_exponentiation_demo(rho,dt,nSteps)
%DENSITY_MATRIX_EXPONENTIATION_DEMO
% Demonstrates the QPCA density-matrix-exponentiation idea using the
% SWAP interaction.
%
% This is a validation/demo layer. The main N-QPCA result uses the exact
% simulator unitary U=exp(2*pi*i*rho) to keep the main experiment compact.
%
% For a system state sigma and an auxiliary copy rho:
%
%   sigma' = Tr_aux[ exp(-i dt S) (sigma kron rho)
%                   exp(+i dt S) ]
%
% Repeated application approximates evolution generated by rho.

rho = (rho+rho')/2;
rho = rho/trace(rho);
d = size(rho,1);

S = swap_operator(d);
W = expm(-1i*dt*S);

sigma = eye(d)/d;

history = zeros(d,nSteps+1);
history(:,1) = real(eig(sigma));

for step = 1:nSteps
    joint = W*kron(sigma,rho)*W';
    sigma = partial_trace_second(joint,d);
    sigma = (sigma+sigma')/2;
    history(:,step+1) = sort(real(eig(sigma)),'descend');
end

out.finalState = sigma;
out.history = history;
out.swapOperator = S;
out.dt = dt;
out.nSteps = nSteps;

end

function S = swap_operator(d)
S = zeros(d*d,d*d);
for i = 1:d
    for j = 1:d
        row = (j-1)*d+i;
        col = (i-1)*d+j;
        S(row,col)=1;
    end
end
end

function rhoA = partial_trace_second(rhoAB,d)
% Basis ordering is A-major then B.
rho4 = reshape(rhoAB,[d,d,d,d]);
rhoA = zeros(d,d);
for a = 1:d
    for ap = 1:d
        rhoA(a,ap) = trace(squeeze(rho4(a,:,ap,:)));
    end
end
end
